// 仅挂载到本轮m415 Linux测试API；同一生产dist与真实认证/适配器，不增加HTTP控制入口。
import {createRequire} from 'node:module';
import {createWriteStream} from 'node:fs';
import {writeFile} from 'node:fs/promises';
import {join,isAbsolute} from 'node:path';
import {performance,monitorEventLoopDelay} from 'node:perf_hooks';
import {controlFileName,createControlInbox} from './module15-performance-control.mjs';
const directory=process.env.M415_PROBE_DIRECTORY,runId=process.env.M415_RUN_ID;
if(process.env.NODE_ENV!=='production'||process.env.M415_ISOLATED_BOOTSTRAP!=='1'||!/^\/m415_[a-f0-9]{32}_test$/.test(new URL(process.env.DATABASE_URL).pathname)||!isAbsolute(directory??'')||!/^[a-f0-9-]{36}$/.test(runId??''))throw new Error('M415探针仅允许本轮独占Linux生产镜像性能进程');
const require=createRequire(new URL('../../package.json',import.meta.url)),{Pool,Client}=require('pg');
class Histogram{constructor(){this.bins=new Uint32Array(1200001);this.count=0;this.max=0;this.overflow=0;}add(ms){const n=Math.ceil(ms*10);if(n<this.bins.length)this.bins[n]++;else this.overflow++;this.count++;this.max=Math.max(this.max,ms);}summary(){const p=x=>{let total=0,target=Math.ceil(this.count*x);if(!target)return null;for(let n=0;n<this.bins.length;n++){total+=this.bins[n];if(total>=target)return n/10;}return this.max;};return {samples:this.count,p50Ms:p(.5),p95Ms:p(.95),p99Ms:p(.99),maxMs:this.max,overflow:this.overflow,precisionMs:.1};}}
let enabled=false,measuredCommand,writer,pool,queries,errors,maxWaiting,maxCapacity,cpuStart,eluStart,started,rssPeak,memorySamples,writerError,backpressure=false,pending=0;
let captureStatements=null;
let nextConnectionId=0;const connectionIds=new WeakMap();
const delay=monitorEventLoopDelay({resolution:20}),safeCode=e=>typeof e?.code==='string'&&/^[A-Z0-9_]{1,40}$/.test(e.code)?e.code:'UNCLASSIFIED';
function record(row){if(!writer)return;if(writer.writableLength>8*1024*1024){backpressure=true;return;}writer.write(JSON.stringify({runId,sessionId:measuredCommand.sessionId,sequence:measuredCommand.sequence,atMs:performance.now()-started,...row})+'\n');}
function observed(original,receiver,args,finish){const begin=performance.now(),callback=args.at(-1);pending++;const end=error=>{try{finish(performance.now()-begin,error);}finally{pending--;}};if(typeof callback==='function'){args[args.length-1]=function(...result){end(result[0]);return Reflect.apply(callback,this,result);};try{return Reflect.apply(original,receiver,args);}catch(error){end(error);throw error;}}try{const result=Reflect.apply(original,receiver,args);if(result&&typeof result.then==='function')return result.then(value=>{end();return value;},error=>{end(error);throw error;});end();return result;}catch(error){end(error);throw error;}}
const connect=Pool.prototype.connect;Pool.prototype.connect=function(...args){if(!enabled)return Reflect.apply(connect,this,args);maxWaiting=Math.max(maxWaiting,this.waitingCount);maxCapacity=Math.max(maxCapacity,this.options.max??0);const result=observed(connect,this,args,(ms,error)=>{pool.add(ms);if(error)errors['POOL:'+safeCode(error)]=(errors['POOL:'+safeCode(error)]??0)+1;record({kind:'pool-acquire',durationMs:ms,errorCode:error?safeCode(error):null,waiting:this.waitingCount});});maxWaiting=Math.max(maxWaiting,this.waitingCount);return result;};
const query=Client.prototype.query;Client.prototype.query=function(...args){if(!enabled)return Reflect.apply(query,this,args);const sql=typeof args[0]==='string'?args[0]:args[0]?.text??'',kind=/auth_session/.test(sql)?'AUTH':/generate_series/.test(sql)?'TRENDS':/audit_log/.test(sql)?'AUDIT':/FROM task|"public"\."task"/i.test(sql)?'TASK':/inventory_balance/.test(sql)?'STOCK':/^\s*(BEGIN|COMMIT|ROLLBACK|SET)/i.test(sql)?'TRANSACTION':'BUSINESS';if(captureStatements){if(captureStatements.length>=128)throw new Error('SQL_CAPTURE_LIMIT');if(!connectionIds.has(this))connectionIds.set(this,++nextConnectionId);const values=(typeof args[0]==='string'?args[1]:args[0]?.values)??[];captureStatements.push({sql,values:Array.isArray(values)?values:[],kind,connectionId:connectionIds.get(this)});}return observed(query,this,args,(ms,error)=>{if(!queries.has(kind))queries.set(kind,new Histogram());queries.get(kind).add(ms);if(error)errors['SQL:'+safeCode(error)]=(errors['SQL:'+safeCode(error)]??0)+1;record({kind:'sql',category:kind,durationMs:ms,errorCode:error?safeCode(error):null});});};
const memoryTimer=setInterval(()=>{if(!enabled)return;const memory=process.memoryUsage();rssPeak=Math.max(rssPeak,memory.rss);memorySamples++;record({kind:'api-memory',...memory});},500);memoryTimer.unref();
let busy=false;const inbox=createControlInbox(directory,runId);
const controlTimer=setInterval(async()=>{if(busy)return;busy=true;let command;try{command=await inbox.next();if(!command)return;
 if(command.action==='start'){if(enabled)throw new Error('probe already measuring');measuredCommand=command;captureStatements=command.capture===true?[]:null;writer=createWriteStream(join(directory,controlFileName('probe',command)),{flags:'wx'});writerError=null;writer.on('error',error=>{writerError=safeCode(error);});pool=new Histogram();queries=new Map();errors={};maxWaiting=0;maxCapacity=0;pending=0;backpressure=false;cpuStart=process.cpuUsage();eluStart=performance.eventLoopUtilization();started=performance.now();rssPeak=process.memoryUsage().rss;memorySamples=1;delay.reset();delay.enable();enabled=true;await reply(command,{action:'started'});}
 else{if(!enabled||command.sessionId!==measuredCommand.sessionId)throw new Error('probe not measuring this session');enabled=false;delay.disable();const elapsedMs=performance.now()-started,cpu=process.cpuUsage(cpuStart),memory=process.memoryUsage();rssPeak=Math.max(rssPeak,memory.rss);await new Promise((accept,reject)=>{writer.end(error=>error?reject(error):accept());});await reply(command,{action:'stopped',measuredSequence:measuredCommand.sequence,rawFile:controlFileName('probe',measuredCommand),poolAcquire:pool.summary(),queries:Object.fromEntries([...queries].map(([key,h])=>[key,h.summary()])),errors,maxWaiting,maxCapacity,pending,writerError,backpressure,resources:{elapsedMs,cpuMicroseconds:cpu,cpuOneCorePercent:(cpu.user+cpu.system)/elapsedMs/10,eventLoopUtilization:performance.eventLoopUtilization(eluStart),eventLoopDelayMs:{p50:delay.percentile(50)/1e6,p95:delay.percentile(95)/1e6,p99:delay.percentile(99)/1e6,max:delay.max/1e6},rssPeakBytes:rssPeak,rssEndBytes:memory.rss,heapUsedEndBytes:memory.heapUsed,memorySamples,samplingIntervalMs:500}});writer=undefined;}
 }catch{if(command)await reply(command,{action:'error',error:'PROBE_CONTROL_FAILED'}).catch(()=>{});}finally{busy=false;}},100);controlTimer.unref();
async function reply(command,value){if(value.action==='stopped'&&captureStatements){value.captureFile=controlFileName('capture',measuredCommand);await writeFile(join(directory,value.captureFile),JSON.stringify(captureStatements)+'\n',{flag:'wx'});captureStatements=null;}await inbox.reply(command,value);}
